using GraphApi.Models.USR.Modelos;namespace GraphApi.Services.USR.Modelos{    /// <summary>    /// Define las operaciones de negocio y persistencia para Modelos.    /// </summary>    public interface IModelosService    {        /// <summary>        /// Obtiene la lista de Modelos con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadModelos>> GetModelos(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Modelos con filtros opcionales.        /// </summary>        /// <param name="modeloID">Filtro opcional para ModeloID.</param>        /// <param name="marcaID">Filtro opcional para MarcaID.</param>        /// <param name="modelo">Filtro opcional para Modelo.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetModelosDynamic(            int? modeloID,            int? marcaID,            string? modelo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Modelo.        /// </summary>        /// <param name="objInput">Datos para crear el Modelo.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadModelos> CreateModelos(            clCreateModelos objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Modelo.        /// </summary>        /// <param name="objInput">Datos para actualizar el Modelo, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadModelos?> UpdateModelos(            clUpdateModelos objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Modelo por su ID.        /// </summary>        /// <param name="nModelosID">ID del Modelo a eliminar.</param>        Task<bool> DeleteModelos(int nModelosID);    }}